CREATE EXTENSION IF NOT EXISTS pg_trgm;

CREATE INDEX idx_title_trgm_gin ON title USING gin (title gin_trgm_ops);
CREATE INDEX idx_cn_country_code ON company_name (country_code);
CREATE INDEX idx_mi_info_type_id_movie_id ON movie_info (info_type_id, movie_id);
CREATE INDEX idx_mi_idx_info_type_id_movie_id ON movie_info_idx (info_type_id, movie_id);
CREATE INDEX idx_mc_company_type_id_movie_id ON movie_companies (company_type_id, movie_id);
CREATE INDEX idx_mc_company_id ON movie_companies (company_id);

-- Optional: Update statistics if they are stale
